bool SignalView::show(CWnd* owner,const std::wstring& ini){closing_=false;if(!GetSafeHwnd()){ini_=ini;if(!Create(IDD_UART_INSTRUMENTS,owner))return false;}ShowWindow(SW_SHOW);SetForegroundWindow();refresh();return true;}
BOOL SignalView::OnInitDialog(){CDialog::OnInitDialog();ui::localize_dialog(m_hWnd);known_.clear();mode_value_=-1;xy_choices_={};shift_=0;max_age_=0.05;tolerance_=0;SetWindowTextW(L"XY / Recorded-run comparison");font_=make_ui_font(m_hWnd,std::wstring(AfxGetApp()->m_lpCmdLine).find(L"--font125")!=std::wstring::npos);
    const auto child=[&](const wchar_t* cls,const wchar_t* label,DWORD style,int id){auto h=ui::create_window(cls,label,WS_CHILD|WS_VISIBLE|style,0,0,1,1,m_hWnd,reinterpret_cast<HMENU>(static_cast<INT_PTR>(id)),nullptr,nullptr);::SendMessageW(h,WM_SETFONT,reinterpret_cast<WPARAM>(font_),FALSE);return h;};
    mode_=child(L"COMBOBOX",L"",CBS_DROPDOWNLIST|WS_TABSTOP,7000);ui::choices(mode_);for(auto label:{L"Live XY",L"Compare runs"})::SendMessageW(mode_,CB_ADDSTRING,0,reinterpret_cast<LPARAM>(label));::SendMessageW(mode_,CB_SETCURSEL,0,0);
    x_=child(L"COMBOBOX",L"",CBS_DROPDOWN|CBS_AUTOHSCROLL|WS_VSCROLL|WS_TABSTOP,7001);y_=child(L"COMBOBOX",L"",CBS_DROPDOWN|CBS_AUTOHSCROLL|WS_VSCROLL|WS_TABSTOP,7002);for(auto h:{x_,y_})::SendMessageW(h,CB_LIMITTEXT,160,0);
    for(const auto& label:std::vector<std::pair<int,const wchar_t*>>{{7010,L"Load run 1..."},{7011,L"Load run 2..."},{7012,L"Align / tolerance..."},{7013,L"Refresh"},{7014,L"Save comparison..."}})buttons_.push_back(child(L"BUTTON",label.second,BS_PUSHBUTTON|WS_TABSTOP,label.first));
    connect_=child(L"BUTTON",L"Connect XY points",BS_AUTOCHECKBOX|WS_TABSTOP,7015);hint_=child(L"STATIC",L"",SS_NOPREFIX,0);status_=child(L"STATIC",L"",SS_NOPREFIX,0);
    const auto cls=AfxRegisterWndClass(0,LoadCursorW(nullptr,IDC_ARROW),GetSysColorBrush(COLOR_3DFACE));canvas_.CreateEx(0,cls,L"Signal view",WS_CHILD|WS_VISIBLE,CRect(0,0,1,1),this,7020);canvas_.draw=[this](CDC& dc,CRect rect){draw(dc,rect);};
    try{wchar_t value[4096]{};GetPrivateProfileStringW(L"SignalView",L"XY",L"",value,4096,ini_.c_str());if(*value){const auto fields=unpack_settings(value,2);xy_choices_={fields[0],fields[1]};::SetWindowTextW(x_,fields[0].empty()?L"(none)":fields[0].c_str());::SetWindowTextW(y_,fields[1].empty()?L"(none)":fields[1].c_str());}GetPrivateProfileStringW(L"SignalView",L"Compare",L"",value,4096,ini_.c_str());if(*value){const auto fields=unpack_settings(value,3);if(!uart_number(fields[0],-1e9,1e9,shift_)||!uart_number(fields[1],0,3600,max_age_)||!uart_number(fields[2],0,1e100,tolerance_))throw std::runtime_error("Invalid comparison ranges.");}}
    catch(...){shift_=0;max_age_=0.05;tolerance_=0;status_text_=L"Invalid saved analysis preferences; review Align / tolerance.";}
    ready_=true;SetWindowPos(nullptr,60,40,1100,800,SWP_NOZORDER);SetTimer(1,500,nullptr);layout();return TRUE;
}
std::string SignalView::key(HWND h)const{const auto value=text(h);return value.empty()||value==L"(none)"?std::string{}:message_utf8(value);}
void SignalView::persist_xy(){if(::SendMessageW(mode_,CB_GETCURSEL,0,0)!=0)return;try{xy_choices_={uart_wide(key(x_)),uart_wide(key(y_))};const auto encoded=pack_settings({xy_choices_[0],xy_choices_[1]});if(!WritePrivateProfileStringW(L"SignalView",L"XY",encoded.c_str(),ini_.c_str()))status_text_=L"Cannot save XY choices.";}catch(...){status_text_=L"Invalid XY choices.";}}
void SignalView::refresh(bool choices){if(!ready_)return;const int mode=static_cast<int>(::SendMessageW(mode_,CB_GETCURSEL,0,0));const auto snapshot=snapshot_?snapshot_():CaptureSnapshot{};
    if(choices){std::set<std::string> keys;if(mode==0)keys.insert(snapshot.keys.begin(),snapshot.keys.end());else for(const auto& name:runs_[0].data.keys)if(std::find(runs_[1].data.keys.begin(),runs_[1].data.keys.end(),name)!=runs_[1].data.keys.end())keys.insert(name);
        if(keys!=known_||mode!=mode_value_){known_=keys;for(auto h:{x_,y_}){auto saved=text(h);::SendMessageW(h,CB_RESETCONTENT,0,0);::SendMessageW(h,CB_ADDSTRING,0,reinterpret_cast<LPARAM>(L"(none)"));for(const auto& name:keys){const auto wide=uart_wide(name);::SendMessageW(h,CB_ADDSTRING,0,reinterpret_cast<LPARAM>(wide.c_str()));}::SetWindowTextW(h,saved.empty()?L"(none)":saved.c_str());}}}
    mode_value_=mode;points_={};::EnableWindow(y_,mode==0);::EnableWindow(connect_,mode==0);for(size_t n=0;n<buttons_.size();++n)::EnableWindow(buttons_[n],n==3||(!busy()&&mode==1));
    if(mode==0){points_[0]=xy_pairs(snapshot,key(x_),key(y_));if(project_){for(auto& p:points_[0]){p.first=project_(key(x_),p.first);p.second=project_(key(y_),p.second);}auto& p=points_[0];p.erase(std::remove_if(p.begin(),p.end(),[](const auto& v){return !std::isfinite(v.first)||!std::isfinite(v.second);}),p.end());}
        ::SetWindowTextW(hint_,L"X channel (middle) / Y channel (right). Same-row pairs only; latest 2000 pairs. Current display scale/offset is applied. Missing values are not paired with old samples.");status_text_=L"Live XY | "+std::to_wstring(points_[0].size())+L" same-row pairs | X: "+uart_wide(key(x_))+L" | Y: "+uart_wide(key(y_));
    }else {comparison_=compare_runs(runs_[0],runs_[1],key(x_),shift_,max_age_,tolerance_);points_[0]=series(runs_[0],key(x_),0);points_[1]=series(runs_[1],key(x_),shift_);
        ::SetWindowTextW(hint_,L"Select one shared signal (middle). Black: run 1; blue: run 2 + time shift. Raw numeric values; nearest one-to-one pairs within the selected time tolerance, no interpolation.");
        status_text_=L"Run 1: "+uart_wide(runs_[0].name)+L" | Run 2: "+uart_wide(runs_[1].name)+L"\r\nMatched "+std::to_wstring(comparison_.matches.size())+L" | PASS "+std::to_wstring(comparison_.passed)+L" | FAIL "+std::to_wstring(comparison_.matches.size()-comparison_.passed)+L" | Unmatched "+std::to_wstring(comparison_.unmatched_a)+L" / "+std::to_wstring(comparison_.unmatched_b)+L" | shift "+number(shift_)+L" s\r\nClock: run 1 "+(runs_[0].provenance.find("SYNTHETIC")!=std::string::npos?L"SYNTHETIC":L"CSV / PC receipt / extracted")+L"; run 2 "+(runs_[1].provenance.find("SYNTHETIC")!=std::string::npos?L"SYNTHETIC":L"CSV / PC receipt / extracted");
    }::SetWindowTextW(status_,status_text_.c_str());::EnableWindow(buttons_[4],mode==1&&!busy()&&!comparison_.matches.empty());layout();canvas_.Invalidate(FALSE);
}
bool SignalView::begin_load(size_t slot,const std::filesystem::path& path){if(closing_||busy()||!options_)return false;const auto options=options_();const bool started=loader_.start([slot,path,options](const std::atomic<bool>& cancel){return Loaded{slot,load_recorded_run(path,options,cancel)};});if(started&&ready_)for(const auto n:{0,1,4})::EnableWindow(buttons_[n],FALSE);return started;}
void SignalView::load(size_t slot){if(busy())return;CFileDialog dialog(TRUE,nullptr,nullptr,OFN_FILEMUSTEXIST|OFN_HIDEREADONLY,L"Recordings (*.bin;*.log;*.txt;*.csv;*.cvs)|*.bin;*.log;*.txt;*.csv;*.cvs|All files (*.*)|*.*||",this);if(dialog.DoModal()==IDOK&&begin_load(slot,std::filesystem::path(dialog.GetPathName().GetString())))::SetWindowTextW(status_,L"Loading in background with the current extraction / offline binary schema. Close cancels; old runs remain until a successful load.");}
void SignalView::poll(){Loaded loaded;std::wstring error;if(loader_.take(loaded,error)){if(error.empty()&&!closing_){runs_[loaded.slot]=std::move(loaded.run);refresh();}else if(!error.empty()&&ready_){refresh();::SetWindowTextW(status_,error.c_str());}}int saved=0;if(saver_.take(saved,error)&&ready_)::SetWindowTextW(status_,error.empty()?L"Comparison CSV saved; source recordings unchanged.":error.c_str());}
void SignalView::settings(){UartToolForm form(L"Run alignment / tolerance",L"Run time zero is its first numeric row. Shift is added to run 2. A sample is paired once with the nearest run-2 sample within the maximum time difference. Value tolerance applies to abs(run2-run1). No interpolation. Unindexed file times are synthetic. Load snapshots the Offline replay interval (100 ms if that page has not been opened).",{{L"Run 2 shift (s)",number(shift_)},{L"Maximum time difference (s)",number(max_age_)},{L"Absolute value tolerance",number(tolerance_)}},{},[](const auto& f,std::wstring& error){double a=0,b=0,c=0;const bool ok=uart_number(f[0],-1e9,1e9,a)&&uart_number(f[1],0,3600,b)&&uart_number(f[2],0,1e100,c);if(!ok)error=L"Enter finite shift, nonnegative time difference and tolerance.";return ok;},this);if(form.DoModal()!=IDOK)return;const auto fields=form.values();const auto encoded=pack_settings(fields);if(!WritePrivateProfileStringW(L"SignalView",L"Compare",encoded.c_str(),ini_.c_str())){::SetWindowTextW(status_,L"Cannot save comparison settings; previous values retained.");return;}uart_number(fields[0],-1e9,1e9,shift_);uart_number(fields[1],0,3600,max_age_);uart_number(fields[2],0,1e100,tolerance_);refresh(false);}
void SignalView::save(){if(busy()||comparison_.matches.empty())return;SYSTEMTIME now{};GetLocalTime(&now);auto filename=capture_filename(now);filename.replace(filename.size()-4,4,L"_compare.csv");CFileDialog dialog(FALSE,L"csv",filename.c_str(),OFN_OVERWRITEPROMPT|OFN_HIDEREADONLY,L"CSV (*.csv)|*.csv||",this);if(dialog.DoModal()!=IDOK||busy())return;const auto data=comparison_csv(comparison_);const auto path=std::filesystem::path(dialog.GetPathName().GetString());saver_.start([path,data](const std::atomic<bool>& cancel){uart_write_file(path,data,std::filesystem::exists(path),cancel);return 1;});}
BOOL SignalView::OnCommand(WPARAM w,LPARAM l){const auto id=LOWORD(w);if(id==7000&&HIWORD(w)==CBN_SELCHANGE){if(::SendMessageW(mode_,CB_GETCURSEL,0,0)==0){::SetWindowTextW(x_,xy_choices_[0].empty()?L"(none)":xy_choices_[0].c_str());::SetWindowTextW(y_,xy_choices_[1].empty()?L"(none)":xy_choices_[1].c_str());}refresh();return TRUE;}if(((id==7001||id==7002)&&(HIWORD(w)==CBN_SELCHANGE||HIWORD(w)==CBN_KILLFOCUS))){persist_xy();refresh();return TRUE;}if(HIWORD(w)==BN_CLICKED){if(id==7010||id==7011){load(id-7010);return TRUE;}if(id==7012){settings();return TRUE;}if(id==7013||id==7015){refresh();return TRUE;}if(id==7014){save();return TRUE;}}return CDialog::OnCommand(w,l);}
void SignalView::OnTimer(UINT_PTR){poll();if(IsWindowVisible()&&::SendMessageW(mode_,CB_GETCURSEL,0,0)==0)refresh();}
void SignalView::OnCancel(){loader_.cancel();ShowWindow(SW_HIDE);}
void SignalView::layout(){if(!ready_)return;CRect r;GetClientRect(&r);const int row=std::max(28,control_font_height(mode_)+12),gap=8;::MoveWindow(mode_,10,10,190,row*7,TRUE);const int combo_width=(r.Width()-226)/2;::MoveWindow(x_,208,10,combo_width,row*12,TRUE);::MoveWindow(y_,216+combo_width,10,combo_width,row*12,TRUE);int x=10,y=row+18;for(auto h:buttons_){const int width=control_text_width(h,24);if(x+width>r.right-10){x=10;y+=row+gap;}::MoveWindow(h,x,y,width,row,TRUE);x+=width+gap;}const int width=control_text_width(connect_,30);if(x+width>r.right-10){x=10;y+=row+gap;}::MoveWindow(connect_,x,y,width,row,TRUE);y+=row+gap;const int help=std::max(row*2,control_wrapped_text_height(hint_,r.Width()-20)+6);::MoveWindow(hint_,10,y,r.Width()-20,help,TRUE);y+=help+gap;const int bottom=std::max(row*3,control_wrapped_text_height(status_,r.Width()-20)+6);canvas_.MoveWindow(10,y,r.Width()-20,std::max(row*3,r.Height()-y-bottom-20));::MoveWindow(status_,10,r.bottom-bottom-5,r.Width()-20,bottom,TRUE);}
void SignalView::draw(CDC& dc,CRect rect){const auto font=dc.SelectObject(CFont::FromHandle(font_));dc.SetBkMode(TRANSPARENT);dc.FillSolidRect(rect,RGB(250,250,250));CRect plot=rect;plot.DeflateRect(85,35,30,50);if(plot.Width()<20||plot.Height()<20){dc.SelectObject(font);return;}
    bool found=false;long double xmin=0,xmax=1,ymin=0,ymax=1;for(const auto& series:points_)for(const auto& point:series){if(!found){xmin=xmax=point.first;ymin=ymax=point.second;found=true;}else{xmin=std::min(xmin,static_cast<long double>(point.first));xmax=std::max(xmax,static_cast<long double>(point.first));ymin=std::min(ymin,static_cast<long double>(point.second));ymax=std::max(ymax,static_cast<long double>(point.second));}}
    const auto expand=[](long double& low,long double& high){if(low!=high)return;const auto margin=std::max(1e-6L,std::abs(low)*0.05L),bound=static_cast<long double>(std::numeric_limits<double>::max());low=low<=-bound+margin?-bound:low-margin;high=high>=bound-margin?bound:high+margin;};expand(xmin,xmax);expand(ymin,ymax);const auto normalized=[](long double value,long double low,long double high){const auto scale=std::max({std::abs(low),std::abs(high),1e-100L});return std::clamp((value/scale-low/scale)/(high/scale-low/scale),0.0L,1.0L);};
    dc.Rectangle(plot);dc.TextOutW(4,plot.top,number(ymax).c_str());dc.TextOutW(4,plot.bottom-20,number(ymin).c_str());dc.TextOutW(plot.left,plot.bottom+8,number(xmin).c_str());dc.TextOutW(std::max(plot.left,plot.right-130),plot.bottom+8,number(xmax).c_str());
    if(!found){dc.TextOutW(plot.left+10,plot.top+10,L"Select channels / load recordings.");dc.SelectObject(font);return;}
    const int saved=dc.SaveDC();dc.IntersectClipRect(plot);for(size_t n=0;n<points_.size();++n){CPen pen(PS_SOLID,1,n?RGB(0,70,150):RGB(35,35,35));const auto old=dc.SelectObject(&pen);auto points=points_[n];if(mode_value_==1&&!points.empty()){std::vector<ChannelSample> timed;for(const auto& p:points)timed.push_back({p.first,p.second});points.clear();for(const auto& p:plot_envelope(timed,static_cast<double>(xmin),static_cast<double>(xmax),plot.Width()))points.push_back({p.t,p.v});}
        bool first=true;for(const auto& p:points){const int x=plot.left+static_cast<int>(normalized(p.first,xmin,xmax)*(plot.Width()-1)),y=plot.bottom-1-static_cast<int>(normalized(p.second,ymin,ymax)*(plot.Height()-1));if(mode_value_==1||::SendMessageW(connect_,BM_GETCHECK,0,0)==BST_CHECKED){if(first)dc.MoveTo(x,y);else dc.LineTo(x,y);}if(mode_value_==0||points.size()==1)dc.FillSolidRect(x-2,y-2,5,5,n?RGB(0,70,150):RGB(35,35,35));first=false;}dc.SelectObject(old);}dc.RestoreDC(saved);dc.SelectObject(font);
}
void SignalView::OnSize(UINT t,int w,int h){CDialog::OnSize(t,w,h);if(t!=SIZE_MINIMIZED)layout();}
void SignalView::OnGetMinMaxInfo(MINMAXINFO* i){CDialog::OnGetMinMaxInfo(i);i->ptMinTrackSize.x=900;i->ptMinTrackSize.y=700;}
LRESULT SignalView::OnDpiChanged(WPARAM,LPARAM l){const auto next=make_ui_font(m_hWnd);if(next){const auto old=font_;font_=next;::EnumChildWindows(m_hWnd,[](HWND h,LPARAM f)->BOOL{::SendMessageW(h,WM_SETFONT,static_cast<WPARAM>(f),FALSE);return TRUE;},reinterpret_cast<LPARAM>(font_));if(old)DeleteObject(old);}if(l){const auto r=reinterpret_cast<RECT*>(l);SetWindowPos(nullptr,r->left,r->top,r->right-r->left,r->bottom-r->top,SWP_NOZORDER|SWP_NOACTIVATE);}layout();canvas_.Invalidate(FALSE);return 0;}
void SignalView::OnDestroy(){ready_=false;KillTimer(1);for(auto h=::GetWindow(m_hWnd,GW_CHILD);h;){const auto next=::GetWindow(h,GW_HWNDNEXT);::DestroyWindow(h);h=next;}CDialog::OnDestroy();if(font_)DeleteObject(font_);font_=nullptr;}
